sys_script_client.script:
function onLoad() {
    //GC User should have only read only access wherever other business is GC XX and read-write access wherever owning business is GC XX
    var isReadonlyAccessToTaskForm = g_scratchpad.isReadonlyAccessToTaskForm;

    if (isReadonlyAccessToTaskForm) {
        var fields = g_form.getEditableFields();

        fields.forEach(function(field) {
            g_form.setReadOnly(field, true);
        });
    }
}
